import React, { useEffect, useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";
import { useNavigate } from "react-router-dom";
import Popup from "./Popup";
import Button from "react-bootstrap/Button";
import axios from "axios";
import { Group } from "../Model/Group.model";
import AddIcon from "@mui/icons-material/Add";
import DeleteIcon from "@mui/icons-material/Delete";
import "./Groups.scss";

function Groups() {
  const navigate = useNavigate();
  const [groups, setGroups] = useState<Group[]>([]);
  const [showPopup, setShowPopup] = useState<boolean>(false);

  useEffect(() => {
    axios
      .get<Group[]>(`http://localhost:5257/api/Group/`)
      .then((response) => {
        setGroups(response.data);
        console.log(response.data);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  const openGroup = (event: any, groupId: string) => {
    event?.stopPropagation();
    navigate(`/group/${groupId}`);
  };
  const handleOpenPopup = () => {
    setShowPopup(true);
  };

  const handleClosePopup = () => {
    setShowPopup(false);
  };

  const onCreate = (value: string) => {
    axios
      .post<Group>("http://localhost:5257/api/Group", { name: value })
      .then((response) => {
        setGroups((old) => [...old, response.data]);
      })
      .catch((error) => {
        alert("Name cannot be empty");
      });
  };

  const checkHandler = (idToUpdate: string, checked: boolean) => {
    const group = groups.find((x) => x.id === idToUpdate);
    if (group != null) {
      setGroups((group) =>
        group.map((x) =>
          x.id === idToUpdate ? { ...x, isChecked: !checked } : x
        )
      );
    }
  };
  return (
    <main className="container my-4">
      <div className="bg-white border-1 d-flex justify-content-between align-items-center mb-3">
        <div>
          <input type="checkbox" className="form-form-check-input me-2" />
          Select all
        </div>
        <div>
          <button className="btn btn-outline-danger btn-sm me-2">
            Delete Selected
          </button>
          <div className="dropdown d-inline">
            <button
              className="btn btn-outline-secondary btn-sm dropdown-toggle"
              data-bs-toggle="dropdown"
            >
              Actions
            </button>
            <ul className="dropdown-menu">
              <li>
                <a className="dropdown-item" href="#">
                  Action 1
                </a>
              </li>
              <li>
                <a className="dropdown-item" href="#">
                  Action 2
                </a>
              </li>
            </ul>
          </div>
        </div>
      </div>

      <div className="border rounder p-3 mb-2 d-flex align-items-center justify-content-between">
        <div className="form-check me-3">
          <input type="checkbox" className="form-check-inout" />
        </div>

        <div className="flex-grow-1">
          <div className=""></div>
        </div>
      </div>
    </main>
  );
}

export default Groups;
